type Reducer<A, B> = readonly [() => B, (acc: B) => B, (acc: B, x: A) => B];
type Transducer<A, B> = (rf: Reducer<B, B>) => Reducer<A, B>;

const map = <A, B>(f: (x: A) => B): Transducer<A, B> =>
  ([init, done, rf]) => [init, done, (acc, x) => rf(acc, f(x))];

const xf = comp(take(3), map(square));          // @thi.ng/transducers: comp, left-to-right
const out = transduce(xf, push<number>(), range(4));   // sink chosen at application time
